insert into public.learning_questions (id, stage_id, display_order, prompt, explanation)
values
  ('d6d18c11-f1bb-4cac-a69d-f6e08d39570a', '61200041-9365-40d2-ac2d-98e1db27c2fb', 1, '23cm와 14cm를 이어 붙였습니다. 전체 길이는 얼마입니까?', '23cm+14cm=37cm이므로 전체 길이는 37cm입니다.'),
  ('18076f7d-6626-4105-8d76-39e3e841965e', '61200041-9365-40d2-ac2d-98e1db27c2fb', 2, '35cm와 22cm를 이어 붙였습니다. 전체 길이는 얼마입니까?', '35cm+22cm=57cm이므로 전체 길이는 57cm입니다.'),
  ('04cdb587-bd52-44d8-9dc6-64e005fe496d', '61200041-9365-40d2-ac2d-98e1db27c2fb', 3, '41cm와 27cm를 이어 붙였습니다. 전체 길이는 얼마입니까?', '41cm+27cm=68cm이므로 전체 길이는 68cm입니다.'),
  ('7084bae0-6b69-4c67-b9cc-dec42a4a9f71', '61200041-9365-40d2-ac2d-98e1db27c2fb', 4, '56cm와 13cm를 이어 붙였습니다. 전체 길이는 얼마입니까?', '56cm+13cm=69cm이므로 전체 길이는 69cm입니다.'),
  ('dc03902e-8d0a-4dc3-b646-807bbfd99562', '61200041-9365-40d2-ac2d-98e1db27c2fb', 5, '18cm와 25cm를 이어 붙였습니다. 전체 길이는 얼마입니까?', '18cm+25cm=43cm이므로 전체 길이는 43cm입니다.'),
  ('d903baaa-1a0b-4835-a047-b91a4e68a85a', '61200041-9365-40d2-ac2d-98e1db27c2fb', 6, '48cm인 끈에서 15cm를 잘랐습니다. 남은 길이는 얼마입니까?', '48cm-15cm=33cm이므로 남은 길이는 33cm입니다.'),
  ('871fe10d-e690-458b-b513-00449bed4c94', '61200041-9365-40d2-ac2d-98e1db27c2fb', 7, '67cm인 끈에서 24cm를 잘랐습니다. 남은 길이는 얼마입니까?', '67cm-24cm=43cm이므로 남은 길이는 43cm입니다.'),
  ('a78f1bf5-6fc4-4047-8653-5d42b9882c77', '61200041-9365-40d2-ac2d-98e1db27c2fb', 8, '59cm인 끈에서 18cm를 잘랐습니다. 남은 길이는 얼마입니까?', '59cm-18cm=41cm이므로 남은 길이는 41cm입니다.'),
  ('6794c8b5-15e4-410a-bfeb-dd73eacf6b7d', '61200041-9365-40d2-ac2d-98e1db27c2fb', 9, '72cm인 끈에서 31cm를 잘랐습니다. 남은 길이는 얼마입니까?', '72cm-31cm=41cm이므로 남은 길이는 41cm입니다.'),
  ('5c69ea52-d9f2-409e-a08b-cdd95e366a75', '61200041-9365-40d2-ac2d-98e1db27c2fb', 10, '86cm인 끈에서 42cm를 잘랐습니다. 남은 길이는 얼마입니까?', '86cm-42cm=44cm이므로 남은 길이는 44cm입니다.'),
  ('6ce9636c-32b1-41a4-b70d-5ac57fcbf2d2', '52000029-29e0-4e4e-80a8-7abf227c7c11', 1, '12m 길의 다음에 7m 길이 이어집니다. 두 길의 전체 길이는?', '12m+7m=19m이므로 전체 길이는 19m입니다.'),
  ('3f93b4db-2e95-4746-937c-6ad2e2e004da', '52000029-29e0-4e4e-80a8-7abf227c7c11', 2, '25m 길의 다음에 14m 길이 이어집니다. 두 길의 전체 길이는?', '25m+14m=39m이므로 전체 길이는 39m입니다.'),
  ('0fdd5a0a-a40b-4e7d-b701-207225a447ca', '52000029-29e0-4e4e-80a8-7abf227c7c11', 3, '31m 길의 다음에 16m 길이 이어집니다. 두 길의 전체 길이는?', '31m+16m=47m이므로 전체 길이는 47m입니다.'),
  ('9c792f63-0fb4-490b-bbef-62a6d2e7484f', '52000029-29e0-4e4e-80a8-7abf227c7c11', 4, '리본이 40cm 있었습니다. 13cm를 사용했다면 남은 길이는?', '40cm-13cm=27cm이므로 남은 리본은 27cm입니다.'),
  ('1ce21161-8f5d-4bbf-a4a9-a1004d715962', '52000029-29e0-4e4e-80a8-7abf227c7c11', 5, '리본이 52cm 있었습니다. 21cm를 사용했다면 남은 길이는?', '52cm-21cm=31cm이므로 남은 리본은 31cm입니다.'),
  ('9f57752c-2711-40e4-b447-3fe54eb7923d', '52000029-29e0-4e4e-80a8-7abf227c7c11', 6, '리본이 63cm 있었습니다. 28cm를 사용했다면 남은 길이는?', '63cm-28cm=35cm이므로 남은 리본은 35cm입니다.'),
  ('d55484be-df0c-4aeb-9a8d-48a0a18341e1', '52000029-29e0-4e4e-80a8-7abf227c7c11', 7, '46cm 막대와 29cm 막대의 길이 차는 얼마입니까?', '더 긴 46cm에서 29cm를 빼면 46-29=17이므로 차는 17cm입니다.'),
  ('5ca88489-02e0-4117-b4dc-e85cd86489b6', '52000029-29e0-4e4e-80a8-7abf227c7c11', 8, '71cm 막대와 38cm 막대의 길이 차는 얼마입니까?', '더 긴 71cm에서 38cm를 빼면 71-38=33이므로 차는 33cm입니다.'),
  ('49d8e34c-c045-41f6-9a81-f2bada9cacfb', '52000029-29e0-4e4e-80a8-7abf227c7c11', 9, '1m와 같은 길이는 어느 것입니까?', '1m=100cm이므로 1m와 같은 길이는 100cm입니다.'),
  ('9ae687f3-e237-4cde-9230-4eb957271029', '52000029-29e0-4e4e-80a8-7abf227c7c11', 10, '2m와 같은 길이를 cm로 나타낸 것은?', '1m=100cm이므로 2m는 100cm가 2번인 200cm입니다.'),
  ('831e9fe3-b631-41b9-9fa6-dacd39d68455', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 1, '18cm+□=47cm입니다. □에 알맞은 길이는?', '47cm-18cm=29cm이므로 빈칸은 29cm입니다.'),
  ('d17edf5c-1dac-4b8b-824b-580f4f21676b', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 2, '26cm+□=61cm입니다. □에 알맞은 길이는?', '61cm-26cm=35cm이므로 빈칸은 35cm입니다.'),
  ('aefc65ac-3c30-405b-a16f-bd0e48748cec', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 3, '35cm+□=79cm입니다. □에 알맞은 길이는?', '79cm-35cm=44cm이므로 빈칸은 44cm입니다.'),
  ('0d470f74-378d-4a74-a854-77e98592fe0d', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 4, '42cm+□=90cm입니다. □에 알맞은 길이는?', '90cm-42cm=48cm이므로 빈칸은 48cm입니다.'),
  ('7b6901cb-26dc-43e6-ba72-18412b7c1a5f', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 5, '74m-□=28m입니다. □에 알맞은 길이는?', '74m-28m=46m이므로 빈칸은 46m입니다.'),
  ('37c4c368-56b5-4582-bd5c-0ad20f987688', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 6, '83m-□=36m입니다. □에 알맞은 길이는?', '83m-36m=47m이므로 빈칸은 47m입니다.'),
  ('51be594b-38a3-4a71-9913-6ea742578ffe', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 7, '65m-□=19m입니다. □에 알맞은 길이는?', '65m-19m=46m이므로 빈칸은 46m입니다.'),
  ('319f8aae-607a-4d39-97d5-c8a49fad7120', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 8, '32cm와 18cm를 이은 뒤 15cm를 잘랐습니다. 남은 길이는?', '32+18=50이고 50-15=35이므로 35cm가 남습니다.'),
  ('f0f5fa81-40c5-4103-8ef7-85eaaf39746f', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 9, '27cm와 24cm를 이은 뒤 19cm를 잘랐습니다. 남은 길이는?', '27+24=51이고 51-19=32이므로 32cm가 남습니다.'),
  ('a7ac8bee-93e2-48c1-9eb1-f1918e2f8009', '21bd2f11-e69b-44eb-9ea7-bdf0ffa53e58', 10, '45cm와 16cm를 이은 뒤 22cm를 잘랐습니다. 남은 길이는?', '45+16=61이고 61-22=39이므로 39cm가 남습니다.'),
  ('f31dc8f6-9365-4f77-b1e7-6a2d067b3a5a', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 1, '35cm+24cm=69cm라고 했습니다. 바르게 고친 것은?', '35+24=59이므로 69cm가 아니라 59cm입니다.'),
  ('302ee39a-efea-440c-b267-4ef22405d27e', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 2, '80cm에서 27cm를 빼면 63cm라고 했습니다. 바른 계산은?', '80-27=53이므로 남은 길이는 53cm입니다.'),
  ('9ca3cda7-8f14-434f-b646-e8046fa5cf74', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 3, '길이가 42cm와 29cm일 때 차를 구하는 식은?', '두 길이의 차는 긴 길이에서 짧은 길이를 빼므로 42-29=13cm입니다.'),
  ('2ad85603-219b-4721-87cb-125f9d9be08b', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 4, '1m=100cm를 바르게 사용한 설명은?', '1m가 100cm이므로 3m는 100cm가 3번인 300cm입니다.'),
  ('134aff17-cca2-432d-bfef-baa365bbb2ce', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 5, '연필 18cm와 자 30cm를 이어 놓았습니다. 전체 길이와 식이 모두 맞는 것은?', '전체 길이는 두 길이를 더해 18+30=48cm입니다.'),
  ('bd44d0ba-0810-4046-a129-33025e3ddab7', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 6, '끈 90cm 중 34cm를 썼습니다. 알맞은 풀이 설명은?', '전체 90cm에서 사용한 34cm를 빼면 56cm가 남습니다.'),
  ('44e6c159-8b94-4b5c-bdb6-c9730f619f05', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 7, '□cm+28cm=73cm의 빈칸과 까닭이 맞는 것은?', '전체 73cm에서 알려진 28cm를 빼면 45cm이므로 빈칸은 45cm입니다.'),
  ('b8dca457-53fa-4a96-8e9d-fa23e0d17276', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 8, '다음 중 단위를 같게 사용한 계산은?', '24cm와 15cm는 같은 단위이고 24+15=39이므로 39cm입니다.'),
  ('aa99e9a4-5770-46f0-9318-61b519f4ab5a', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 9, '56m 길과 38m 길의 차를 94m라고 했습니다. 오류를 바르게 설명한 것은?', '차이는 두 길이를 더하지 않고 긴 길이에서 짧은 길이를 빼므로 18m입니다.'),
  ('46b976f7-33e5-432e-a834-f8053dc59ba5', 'da4dcc57-0bcb-4493-90af-d77c7ecb41c0', 10, '25cm+□=60cm이고 □에서 12cm를 잘랐습니다. 마지막에 남는 길이는?', '빈칸은 60-25=35cm이고 여기서 12cm를 빼면 23cm가 남습니다.');

